// Grab the n8n execution ID and format the IST timestamp
const executionId = \$execution.id || "manual-test";
const currentTime = new Date().toLocaleString("en-US", { timeZone: "Asia/Kolkata" });

// Extract the classifier text safely (Groq/OpenAI-style response, with Gemini fallback)
const aiResponseText = $input.item.json.choices?.[0]?.message?.content
    \vert{}\vert{} $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text
    || "";

// Fail closed: if the classifier was unavailable, do not mark the message as SAFE
const classifierFailed = !aiResponseText;
const isInjection = aiResponseText.toUpperCase().includes("INJECTION");

let verdict = classifierFailed ? "UNVERIFIED" : (isInjection ? "INJECTION DETECTED" : "SAFE");
let summary = classifierFailed
    ? "Classifier unavailable - message blocked as a precaution."
    : (isInjection 
        ? "Blocked malicious prompt injection attempt." 
        : "Message verified successfully.");

// Build the required strict format string
const formattedMessage = `🟣 NGP-032 | exec #${executionId} | ${currentTime} IST | ${verdict} | ${summary}`;

// Pass the chat ID, formatted text, and raw verdict down to the next node
return [{ 
    json: { 
        chatId: \$('Telegram Trigger').first().json.message.chat.id, 
        text: formattedMessage,
        verdict: verdict
    } 
}];
